"""Build PhotoReject's public product, support and privacy pages."""
from pathlib import Path
from html import escape

root = Path(__file__).parent / 'docs'
root.mkdir(parents=True, exist_ok=True)
css = '''@font-face{font-family:Barlow;src:url('/photoreject-policies/assets/BarlowCondensed-ExtraBoldItalic.ttf');font-weight:800;font-style:italic;font-display:swap}*{box-sizing:border-box}body{margin:0;background:#fff3d4;color:#242323;font:18px/1.65 system-ui,sans-serif}a{color:#263ec6;text-underline-offset:4px}header,main,footer{width:min(100% - 48px,1080px);margin:auto}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:28px 0;border-bottom:2px solid #242323}.logo{font:italic 800 clamp(28px,5vw,40px)/1 Barlow,sans-serif;color:#ed4126;text-decoration:none;letter-spacing:-1px;display:flex;gap:12px;align-items:center}.logo svg{width:38px;height:38px;flex-shrink:0}nav{display:flex;gap:24px;font-size:16px}main{padding:64px 0 80px}.eyebrow{font-size:14px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#263ec6}h1,h2{font-family:Barlow,sans-serif;font-weight:800;font-style:italic;line-height:.98;text-transform:uppercase}h1{font-size:clamp(56px,10vw,110px);letter-spacing:-.025em;max-width:850px;margin:20px 0 28px}h1 span{color:#ed4126}h2{font-size:36px;margin:44px 0 16px}.lead{font-size:22px;line-height:1.55;max-width:710px}.copy{max-width:760px}.copy p,.copy li{max-width:70ch}.cta{display:inline-block;background:#263ec6;color:white;text-decoration:none;padding:15px 26px;font:italic 800 25px Barlow,sans-serif;box-shadow:5px 5px 0 #242323;margin:20px 14px 12px 0}.strip{margin-top:48px;background:#ffd747;border-block:2px solid;padding:22px;font-weight:750}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin-top:46px}.steps section{border-top:3px solid #ed4126}.steps h2{margin-top:20px}.steps p{font-size:17px}footer{border-top:2px solid;padding:25px 0 40px;font-size:14px;display:flex;gap:24px;flex-wrap:wrap}summary{font-size:21px;font-weight:700;cursor:pointer;padding:20px 0}details{border-bottom:1px solid #aaa18b}details p{margin:0 0 22px}.notice{padding:20px 24px;border-left:5px solid #ed4126;background:#fff9e9}a:focus-visible,summary:focus-visible{outline:3px solid #263ec6;outline-offset:5px}@media(max-width:650px){header{align-items:flex-start;flex-direction:column;padding:24px 0}main{padding:38px 0 55px}.steps{grid-template-columns:1fr;gap:12px}.lead{font-size:20px}nav{gap:24px}h1{font-size:62px}.copy h1{font-size:52px}}'''
(root/'style.css').write_text(css)
symbol = (root/'assets/reject-mark.svg').read_text()
def page(path,title,desc,body):
    target=root/path/'index.html';target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | PhotoReject</title><meta name="description" content="{escape(desc)}"><link rel="icon" href="/photoreject-policies/assets/icon.png"><link rel="stylesheet" href="/photoreject-policies/style.css"></head><body><header><a class="logo" href="/photoreject-policies/" aria-label="PhotoReject home">PHOTOREJECT{symbol}</a><nav aria-label="Main"><a href="/photoreject-policies/support/">Support</a><a href="/photoreject-policies/privacy/">Privacy</a><a href="/photoreject-policies/terms/">Terms</a></nav></header><main>{body}</main><footer><span>© 2026 Studio EC</span><a href="/photoreject-policies/support/">Get help</a><a href="/photoreject-policies/privacy/">Privacy policy</a><a href="/photoreject-policies/terms/">Terms of use</a><a href="mailto:support@studioec.nl">support@studioec.nl</a></footer></body></html>''')

page(Path('.'),'Less junk. More good stuff.','PhotoReject is a free iPhone photo cleaner. Compare similar shots, protect your favorites, and review every deletion.', '''<p class="eyebrow">The photo cleaner with a little attitude</p><h1>Less junk.<br><span>More good stuff.</span></h1><p class="lead">Eight versions of the same moment? Keep the one you love. PhotoReject helps you sort similar shots, old screenshots and videos — with the final call always yours.</p><a class="cta" href="/photoreject-policies/support/">MEET YOUR CLEANUP ROUTINE</a><p>For iPhone · iOS 17 or later · App Store release in preparation</p><div class="strip">Free cleanup. No ads. Optional Pro video compression.</div><div class="steps"><section><h2>Find the double takes.</h2><p>An on-device scan compares locally available photos taken close together. Open a group and choose your keeper.</p></section><section><h2>Build a reject pile.</h2><p>Review screenshots, videos and your library. Protect the good stuff. Change your mind before cleaning.</p></section><section><h2>You make the cut.</h2><p>Review the pile, then confirm deletion with Apple Photos. Favorites and protected photos stay out of the pile.</p></section></div><section class="copy"><h2>Keep the clip. Lose the bulk.</h2><p>Optional PhotoReject Pro is a one-time in-app purchase for video compression. Choose up to 720p or 1080p, preview the quality and compare file sizes. Save a new copy first, then optionally delete the original with confirmation. Favorites and protected videos stay safe.</p><p>Compression reduces quality. Savings vary by video, and some files cannot be made smaller. The App Store displays your local price before purchase. All cleanup tools remain free, with no subscription.</p><h2>Your photos stay yours.</h2><p>PhotoReject performs its photo analysis on your iPhone. It has no photo-upload service, tracking or advertising SDKs. You choose full or limited access to your library.</p><p class="notice">Deleting through PhotoReject deletes from Apple Photos, including synced devices when iCloud Photos is enabled. Photos normally keeps deleted items in Recently Deleted for 30 days. Storage may not free up immediately.</p></section>''')

page(Path('privacy'),'Privacy policy','How PhotoReject uses photo-library permission, stores your choices locally, and handles support requests.', '''<article class="copy"><p class="eyebrow">Last updated 19 November 2026</p><h1>Your photos.<br><span>Your business.</span></h1><p class="lead">PhotoReject does not upload your photos or videos to Studio EC. Its cleanup and similarity analysis run on your device.</p><h2>Who provides PhotoReject?</h2><p>PhotoReject is provided by Studio EC (Elmar Van Cleynenbreugel). For privacy questions, email <a href="mailto:support@studioec.nl">support@studioec.nl</a>.</p><h2>Photo-library permission</h2><p>You can allow full access, select specific items, or decline access. PhotoReject reads accessible photos, videos and relevant metadata, including creation dates, dimensions, media type and favorite status, to display your library and suggest similar groups. Hidden items are excluded. Change access at any time in iPhone Settings.</p><h2>What stays on your device</h2><p>The app stores protected and rejected item identifiers, cleanup counts and the date of its last rating request in its local app storage. It caches mathematical image features locally to avoid repeating analysis. It does not identify people or create face profiles. Removing the app removes its local choices and cache; this does not restore photos already deleted from your library.</p><h2>iCloud and deletion</h2><p>Scanning uses locally available images and does not download originals from iCloud. If an original is unavailable in a detail view, you can choose to load it from iCloud through Apple Photos. This transfer is handled by Apple, not a PhotoReject server.</p><p>After you review and confirm a cleanup, PhotoReject asks Apple Photos to delete the selected items. With iCloud Photos enabled, that change can sync to other devices. Deleted items normally remain recoverable in Photos → Recently Deleted for 30 days, subject to Apple's behavior and your own actions.</p><h2>No tracking or advertising</h2><p>The app has no account system, advertising, third-party analytics or tracking SDKs. Studio EC does not collect app usage, location, contacts or photo-library contents through PhotoReject. Apple may separately process App Store and diagnostic information under your Apple settings and Apple's privacy policy.</p><h2>Optional Pro purchases and compression</h2><p>Video compression runs on your device. Temporary output files are stored locally while you preview them and removed when you close the compression screen. A copy is added to your Photos library only when you choose Save. The original is retained unless you separately choose and confirm Delete original after the saved copy is verified.</p><p>Apple handles the optional one-time Pro purchase, payment and restoration. PhotoReject checks verified purchase entitlements on your device. Studio EC does not receive your payment details through the app. Apple processes purchase information under its own policies.</p><h2>Ratings and support</h2><p>After a successful cleanup, the app may ask Apple to display its standard rating prompt. Apple controls whether it appears. If you email support, your email address and the information you choose to send are used to respond to that request. Please do not send private photos or other sensitive information unless needed for your question. You can ask us to delete support correspondence.</p><h2>This website</h2><p>These pages do not include analytics scripts, advertising or embedded third-party media. These pages are hosted on GitHub Pages. GitHub may receive technical request information, such as your IP address, to deliver and secure the website. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>. Following links or opening an email app is subject to those services' own policies.</p><h2>Changes</h2><p>We will update this page and its date when the app's privacy practices change. Contact us with questions about your information or this policy.</p></article>''')

page(Path('support'),'Help & support','Get help with PhotoReject permissions, similar-photo scans, safe cleanup, recovery and ratings.', '''<article class="copy"><p class="eyebrow">A little help for your camera roll</p><h1>Good questions.<br><span>Clear answers.</span></h1><p class="lead">Need a hand? Email <a href="mailto:support@studioec.nl?subject=PhotoReject%20support">support@studioec.nl</a> with your iPhone model, iOS version and what happened. Please leave private photos out of your message.</p><details open><summary>How do I clean up?</summary><p>Open a category. In similar groups, choose a keeper and add extras to the reject pile. For other items, use the reject control. Open your reject pile, review each item, then choose Delete and confirm with Apple Photos. You can undo your choices before deleting.</p></details><details><summary>Does PhotoReject cost anything?</summary><p>All scanning, reviewing and deleting tools are free. Optional PhotoReject Pro unlocks video compression with a one-time in-app purchase. There are no subscriptions or ads. Apple displays the local price before you confirm. Restore a prior purchase in Settings → PhotoReject Pro → Restore Purchases.</p></details><details><summary>How does Pro compression work?</summary><p>Choose a video, select up to 720p or 1080p, then make a smaller copy. Compare the preview and actual file sizes. Save the copy to Photos first. You can then choose Delete original, with confirmation; keeping it is the default. Favorites and protected originals are kept. Compression can reduce quality and change HDR appearance, frame rate or metadata. Some videos cannot be made smaller.</p></details><details><summary>Why can I only see some photos?</summary><p>You may have granted limited library access. Use Manage Access in the app or open iPhone Settings → Apps → PhotoReject → Photos to change it. Items outside that permission and hidden items cannot be scanned or reviewed.</p></details><details><summary>What does the similar-photo scan find?</summary><p>It compares locally available photos taken within approximately 15 minutes of each other and with a similar shape. Suggestions are visual matches, not a guarantee of duplicate files. Screenshots are reviewed separately. Photos stored only in iCloud may be skipped. Review every suggestion and choose your own keeper.</p></details><details><summary>Can I recover a deleted photo?</summary><p>Open Apple Photos → Recently Deleted, unlock it if asked, select the item and choose Recover. Apple normally keeps deleted items there for 30 days unless you permanently delete them sooner. PhotoReject does not empty Recently Deleted.</p></details><details><summary>Why hasn't my storage changed?</summary><p>Apple Photos manages storage and Recently Deleted. Space may not be reclaimed immediately, and iCloud optimization affects what is stored locally. PhotoReject does not claim an estimated number of gigabytes saved or clean other apps, contacts or system files.</p></details><details><summary>Will deletion affect iCloud or my other devices?</summary><p>Yes, if iCloud Photos is enabled, deleting from your library can sync across devices. Read the final confirmation carefully.</p></details><details><summary>Are favorites protected?</summary><p>Yes. Favorites and items you mark Keep are excluded from the reject pile. Similar groups retain at least one keeper. If the library changes before deletion, the app rechecks your choices.</p></details><details><summary>Where is the rating prompt?</summary><p>The app asks Apple for a rating prompt after a successful cleanup, with a cooldown between requests. Apple decides when to display it. You can also review PhotoReject from its App Store page after release.</p></details><details><summary>Can I use it offline?</summary><p>Yes, locally available photos can be reviewed and scanned offline. Loading an original from iCloud, visiting support pages and App Store ratings require a connection.</p></details><p class="notice">PhotoReject requires iPhone with iOS 17 or later. Read the <a href="/photoreject-policies/privacy/">privacy policy</a> for details about local storage and permissions.</p></article>''')
print('Built PhotoReject product, privacy and support pages.')

page(Path('terms'),'Terms of use','PhotoReject uses Apple’s standard app license. Learn about free cleanup, optional Pro purchases and safe video compression.', '''<article class="copy"><p class="eyebrow">Last updated 19 November 2026</p><h1>Clear terms.<br><span>No surprises.</span></h1><p class="lead">PhotoReject uses <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple’s Standard Licensed Application End User License Agreement</a>. This page explains the app’s features and purchase arrangements; it does not replace that agreement.</p><h2>Free cleanup</h2><p>Scanning, reviewing and deleting accessible photos and videos are free. PhotoReject has no advertisements, subscriptions or account requirement.</p><h2>Optional PhotoReject Pro</h2><p>Pro is a one-time, non-consumable in-app purchase that unlocks video compression. Apple displays the price for your region before you confirm. Apple handles payment. Restore an existing purchase with the same Apple Account through Settings → PhotoReject Pro → Restore Purchases. For purchase or refund help, visit <a href="https://reportaproblem.apple.com/">Apple’s purchase support</a>. Apple handles refund requests under its applicable policies.</p><h2>Your final decision</h2><p>Similar-photo groups are suggestions. Review every item before deletion. With iCloud Photos enabled, deletions can sync to other devices. Photos normally keeps deleted items in Recently Deleted for 30 days, unless they are permanently removed sooner. PhotoReject does not empty Recently Deleted.</p><h2>Video compression</h2><p>Compression is lossy: quality, HDR appearance, frame rate or metadata may change. Savings depend on the original; not every video can be made smaller. Preview the complete result before saving. PhotoReject keeps the original by default and offers deletion only after a new copy is saved and verified in Photos. Favorites and protected originals are retained. Apple Photos controls when storage space is reclaimed.</p><h2>Privacy and help</h2><p>Read our <a href="/photoreject-policies/privacy/">privacy policy</a> and <a href="/photoreject-policies/support/">support guide</a>. PhotoReject is provided by Studio EC (Elmar Van Cleynenbreugel). Contact <a href="mailto:support@studioec.nl">support@studioec.nl</a> for app support.</p></article>''')
